/**
 * Activepieces Code piece — Service C, Stack C1: the CRM follow-up scanner.
 *
 * Runs inside the **C-draft** flow (Webhook trigger). Pulls the contacts Service A
 * has already mailed straight from **the CRM**, works out who is due a follow-up
 * (touch count < schedule length AND not replied AND enough days since the last
 * touch), and writes a personalised draft per contact. Those drafts become rows in
 * the **Followup-Outbox** sheet; nothing is sent here — a human approves first.
 *
 * Flow:  Webhook -> THIS -> Loop(outboxRows)->Sheets Insert Row (Followup-Outbox)
 *        -> HTTP POST /handoff  (the interlock that unlocks the C-send button).
 *
 * SOURCE OF TRUTH IS CRM. Service A writes the CRM identity-only, so the follow-up
 * state fields below must exist on the Contact for this to have anything to read.
 * Create them once (or map existing ones via the *Field inputs):
 *   - touchCountField   (default 'Touch_Count',   number)  how many touches so far
 *   - lastTouchField    (default 'Last_Touch_At',  datetime) when the last one went
 *   - replyStatusField  (default 'Follow_Up_Status', text) 'replied'/'opted_out' etc.
 * The C-send flow's c3 step writes touchCount + lastTouch back after each send, and
 * the reply handler should set replyStatus='replied' so follow-ups stop.
 *
 * INPUTS
 *   the CRMAccessToken  = {{connections['the CRM'].access_token}}   (required)
 *   apiDomain        = the CRM DC host (default https://www.the CRMapis.com; .in/.eu/…)
 *   apiVersion       = default 'v2'
 *   maxContacts      = safety cap on how many contacts to pull (default 2000)
 *   followupSchedule = days after FIRST touch each follow-up is due; default [4,7,14,30]
 *   maxDrafts        = cap drafts produced per run (default 50)
 *   senderName       = default 'the sender'
 *   catalogUrl       = optional
 *   touchCountField / lastTouchField / replyStatusField = the CRM field API names (see above)
 *
 * OUTPUT { outboxRows, drafts, stats }
 *   outboxRows feed the Followup-Outbox insert loop. Columns match the sheet:
 *   touchNo, contact, client, country, to, subject, body, approved, status,
 *   the CRMId, buyerKey, queuedAt.
 */

export const code = async (inputs) => {
  const token = String(inputs.the CRMAccessToken || '').trim();
  const apiDomain = String(inputs.apiDomain || 'https://www.the CRMapis.com').replace(/\/+$/, '');
  const apiVersion = String(inputs.apiVersion || 'v2').replace(/^\/+|\/+$/g, '');
  const maxContacts = Number(inputs.maxContacts) > 0 ? Number(inputs.maxContacts) : 2000;
  const maxDrafts = Number(inputs.maxDrafts) > 0 ? Number(inputs.maxDrafts) : 50;
  const senderName = inputs.senderName || 'the sender';
  const catalogUrl = inputs.catalogUrl || '';
  const schedule = Array.isArray(inputs.followupSchedule) && inputs.followupSchedule.length
    ? inputs.followupSchedule.map(Number)
    : [4, 7, 14, 30];

  const F_TOUCH = String(inputs.touchCountField || 'Touch_Count');
  const F_LAST = String(inputs.lastTouchField || 'Last_Touch_At');
  const F_REPLY = String(inputs.replyStatusField || 'Follow_Up_Status');

  if (!token) {
    return { outboxRows: [], drafts: [], stats: { error: 'no the CRMAccessToken' } };
  }

  const STOP_STATUSES = new Set(['replied', 'bounced', 'unsubscribed', 'closed', 'opted_out']);
  const now = Date.now();
  const daysSince = (iso) => {
    const t = Date.parse(iso);
    return isNaN(t) ? Infinity : (now - t) / 86400000;
  };
  const clean = (s) => (s === null || s === undefined ? '' : String(s)).replace(/\s+/g, ' ').trim();
  const firstName = (full) => clean(full).split(' ')[0] || '';

  // ---- pull mailed contacts from the CRM (paged) --------------------------------
  const base = `${apiDomain}/crm/${apiVersion}/Contacts`;
  const fields = [
    'Email', 'First_Name', 'Last_Name', 'Full_Name', 'Account_Name',
    'Mailing_Country', 'Description', F_TOUCH, F_LAST, F_REPLY,
  ].filter((v, i, a) => v && a.indexOf(v) === i);

  const contacts = [];
  let page = 1;
  try {
    while (contacts.length < maxContacts) {
      const url = `${base}?fields=${encodeURIComponent(fields.join(','))}` +
        `&per_page=200&page=${page}`;
      const r = await fetch(url, {
        headers: { Authorization: 'the CRM-oauthtoken ' + token },
        signal: AbortSignal.timeout(30000),
      });
      if (r.status === 204) break; // no more records
      if (!r.ok) {
        return { outboxRows: [], drafts: [],
          stats: { error: 'the CRM fetch ' + r.status, page } };
      }
      const j = await r.json().catch(() => ({}));
      const batch = Array.isArray(j.data) ? j.data : [];
      contacts.push(...batch);
      const more = j.info && j.info.more_records;
      if (!more || batch.length === 0) break;
      page++;
    }
  } catch (e) {
    return { outboxRows: [], drafts: [], stats: { error: String(e && e.message) } };
  }

  // ---- personalised, escalating nudges (zero-cost, templated by touch no.) ----
  const followupBody = (name, country, n) => {
    const hi = `Hi${name ? ' ' + name : ' team'},\n\n`;
    const sig = `\n\n${senderName}, Acme Exports` +
      (catalogUrl ? `\nCatalogue: ${catalogUrl}` : '');
    const us = /^(usa|us|united states|u\.s\.a?\.?)$/i.test(clean(country));
    const msg = {
      1: `Just floating this back to the top of your inbox — happy to send a few ` +
         `bagasse tableware samples and a landed-cost quote for the SKUs you move most. ` +
         `Worth a quick look?`,
      2: `Following up with something concrete: share the 3–4 SKUs you import most ` +
         `and I'll send Ex-factory + FOB pricing and free samples. No commitment — ` +
         `just a like-for-like cost comparison against your current supplier.`,
      3: (us
          ? `With the current tariff picture on Chinese goods, a certified India source ` +
            `is worth pricing out. `
          : ``) +
         `Switching is easier than it sounds — we match product weight and OGR so your ` +
         `spec doesn't change, and handle shipping end to end. Open to a 10-min call?`,
      4: `Last note from me on this — if a certified India supplier for your bagasse ` +
         `tableware is worth exploring this quarter, I'll share pricing and samples. ` +
         `If the timing's off, no worries and I'll close this out — just reply either way.`,
    };
    return hi + (msg[n] || msg[4]) + sig;
  };

  const outboxRows = [];
  const drafts = [];
  const nowIso = new Date().toISOString();
  const stats = { pulled: contacts.length, due: 0, maxedOut: 0, notYet: 0,
    replied: 0, noEmail: 0 };

  for (const c of contacts) {
    const email = clean(c.Email);
    if (!email.includes('@')) { stats.noEmail++; continue; }

    const replyStatus = clean(c[F_REPLY]).toLowerCase();
    if (STOP_STATUSES.has(replyStatus)) { stats.replied++; continue; }

    const count = Number(c[F_TOUCH] || 0);
    if (count >= schedule.length) { stats.maxedOut++; continue; }

    // due when enough days have passed since the last touch for this step.
    // Base the clock off Last_Touch_At; if missing (never followed up yet),
    // this contact is treated as due immediately for its next nudge.
    const dueGap = schedule[count];
    const sinceLast = c[F_LAST] ? daysSince(c[F_LAST]) : Infinity;
    if (sinceLast < dueGap) { stats.notYet++; continue; }

    const name = clean(c.Full_Name) || clean(`${c.First_Name || ''} ${c.Last_Name || ''}`);
    const client = clean(c.Account_Name && (c.Account_Name.name || c.Account_Name)) || name;
    const country = clean(c.Mailing_Country);
    const touchNo = count + 1;
    const subject = 'Re: ' + 'Bagasse tableware from India';
    const body = followupBody(firstName(name), country, touchNo);

    const row = {
      touchNo,
      contact: name,
      client,
      country,
      to: email,
      subject,
      body,
      approved: '',           // human sets 'yes'
      status: 'pending',
      the CRMId: clean(c.id),
      buyerKey: (client || email).toLowerCase(),
      queuedAt: nowIso,
    };
    outboxRows.push(row);
    drafts.push(row);
    stats.due++;
    if (outboxRows.length >= maxDrafts) { stats.heldByCap = true; break; }
  }

  return { outboxRows, drafts, stats };
};

/**
 * Service C — POST /handoff (step C5). The interlock: tells the control plane the
 * follow-up drafts are staged in the sheet, which is what flips the C-send button
 * from disabled to enabled. Leaving this out is why a send button stays greyed.
 *
 * INPUTS
 *   crmBaseUrl = default https://your-crm.example.com
 *   crmToken   = CRM_API_TOKEN (bearer). Blank -> handoff is skipped (button stays locked).
 *   button     = which send button to unlock (default 'C-send')
 *   count      = how many drafts were staged (for the control plane to display)
 *   batch      = optional batch id
 */
export const code = async (inputs) => {
  const base = String(inputs.crmBaseUrl || 'https://your-crm.example.com').replace(/\/+$/, '');
  const token = String(inputs.crmToken || '').trim();
  const button = String(inputs.button || 'C-send');
  const count = Number(inputs.count || 0);
  const batch = String(inputs.batch || ('C-' + new Date().toISOString().slice(0, 19)));
  if (!token) return { skipped: 'no crmToken — button stays locked', button };
  try {
    const r = await fetch(base + '/handoff', {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
      body: JSON.stringify({ service: 'C', button, staged: count, batch, ready: true }),
      signal: AbortSignal.timeout(30000),
    });
    const body = await r.json().catch(() => ({}));
    return { status: r.status, button, ...body };
  } catch (e) {
    return { error: String(e && e.message), button };
  }
};
